+// qwenCloudSection returns the text of the QwenCloud section, from its heading to the next heading.
+func qwenCloudSection(t *testing.T, page string) string {
+	t.Helper()
+	_, rest, ok := strings.Cut(page, "### QwenCloud\n")
+	if !ok {
+		t.Fatal("docs/providers.md has no QwenCloud section")
+	}
+	if i := strings.Index(rest, "\n#"); i >= 0 {
+		rest = rest[:i]
+	}
+	return rest
+}
+
+func TestProvidersGuideSaysTheQwenBuildEvidenceCameThroughTheFleetProxy(t *testing.T) {
+	page := readProvidersGuide(t)
+	if n := strings.Count(strings.ToLower(page), "fleet proxy"); n != 1 {
+		t.Fatalf("docs/providers.md names the fleet proxy %d times, want once", n)
+	}
+	var after []string
+	seenLabel := false
+	for _, line := range strings.Split(qwenCloudSection(t, page), "\n") {
+		if seenLabel && strings.TrimSpace(line) != "" {
+			after = append(after, line)
+		}
+		if line == qwenLabel {
+			seenLabel = true
+		}
+	}
+	if !seenLabel || len(after) == 0 {
+		t.Fatal("the QwenCloud section has no label line followed by text")
+	}
+	sentence := strings.ToLower(after[0])
+	for _, want := range []string{"fleet proxy", "direct public-install build", "still under test"} {
+		if !strings.Contains(sentence, want) {
+			t.Errorf("the line after the QwenCloud label does not contain %q: %s", want, after[0])
+		}
+	}
+	if strings.Contains(strings.TrimSuffix(strings.TrimSpace(after[0]), "."), ". ") {
+		t.Errorf("the line after the QwenCloud label is more than one sentence: %s", after[0])
+	}
+}
